protected static void deleteFile(String fileName) {
    if (fileName == null || fileName.trim().isEmpty()) {
        throw new IllegalArgumentException("fileName must not be null or empty");
    }

    java.io.File file = new java.io.File(fileName);

    if (!file.exists() || !file.isFile()) {
        // Nothing to delete
        return;
    }

    try {
        boolean deleted = file.delete();
        if (!deleted) {
            // If deletion fails (e.g., file is open or read‑only), throw an exception so callers are aware
            throw new RuntimeException("Failed to delete file: " + fileName);
        }
    } catch (SecurityException se) {
        // Security exception encountered while attempting deletion
        throw new SecurityException("Permission denied to delete file: " + fileName, se);
    }
}

