private TreeNode<T> rotateRight(TreeNode<T> node){
    try {
        if (node == null) return null;
        // No rotation possible if left child is absent
        if (node.left == null) return node;
        // Perform right rotation
        TreeNode<T> leftChild = node.left;
        node.left = leftChild.right;
        leftChild.right = node;
        return leftChild;
    } catch (Exception e) {
        // In case of unexpected runtime issues, return the original node
        return node;
    }
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> left = node.left;
    if (left == null) return node; // cannot rotate if no left child
    TreeNode<T> rightOfLeft = left.right;

    // Perform rotation
    left.right = node;
    node.left = rightOfLeft;
    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    // Update parent references
    left.parent = node.parent;
    if (node.parent != null) {
        if (node.parent.left == node) {
            node.parent.left = left;
        } else {
            node.parent.right = left;
        }
    }
    node.parent = left;

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        // Cannot perform a right rotation if there is no left child.
        return node;
    }
    // Perform rotation
    node.left = leftChild.right;
    leftChild.right = node;
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check for null input
    if (node == null) {
        throw new IllegalArgumentException("Node to rotate cannot be null");
    }

    // Left child must exist for a right rotation
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        throw new IllegalArgumentException("Node does not have a left child; right rotation cannot be performed");
    }

    // Save parent's reference before changes
    TreeNode<T> parent = node.parent;

    // Perform the rotation
    // Step 1: node's left becomes leftChild's right
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    // Step 2: leftChild's right becomes node
    leftChild.right = node;

    // Step 3: Update parents
    leftChild.parent = parent;
    node.parent = leftChild;

    // Step 4: Reconnect leftChild with the original parent if it existed
    if (parent != null) {
        if (parent.left == node) {
            parent.left = leftChild;
        } else if (parent.right == node) {
            parent.right = leftChild;
        }
    }

    // leftChild is the new parent of node after rotation
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> pivot = node.left;
    node.left = pivot.right;
    if (pivot.right != null) {
        pivot.right.parent = node;
    }
    pivot.parent = node.parent;
    node.parent = pivot;
    pivot.right = node;
    return pivot;
}

