public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    try {
        // Timestamp
        sb.append("[");
        sb.append(new java.util.Date(event.getTimeStamp()));
        sb.append("] ");
        // Level
        sb.append("[");
        sb.append(event.getLevel());
        sb.append("] ");
        // Thread name
        String threadName = event.getThreadName();
        if (threadName != null) {
            sb.append("(").append(threadName).append(") ");
        }
        // Logger name
        sb.append(event.getLoggerName()).append(" - ");
        // Message
        String msg = event.getRenderedMessage();
        sb.append(msg != null ? msg : "");
        // Throwable
        if (event.getThrowableInformation() != null) {
            Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator());
                sb.append(t.toString()).append(System.lineSeparator());
                for (StackTraceElement ste : t.getStackTrace()) {
                    sb.append("\tat ").append(ste).append(System.lineSeparator());
                }
            }
        }
    } catch (Exception e) {
        // Return a fallback description if formatting fails
        sb.setLength(0);
        sb.append("LoggingEvent format error: ").append(e.getMessage());
    }
    return sb.toString();
}

