private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < -1 || end >= headerPart.length()) {
        throw new IllegalArgumentException("end must be between -1 and headerPart.length() - 1");
    }
    int index = end + 1;
    while (index < headerPart.length() - 1) {
        if (headerPart.charAt(index) == '\r' && headerPart.charAt(index + 1) == '\n') {
            return index;
        }
        index++;
    }
    return -1; // no CRLF found
}

private int parseEndOfLine(String headerPart, int end) {
    // Validate input
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds");
    }

    // Search for the CRLF sequence starting from 'end'
    int crlfIndex = headerPart.indexOf("\r\n", end);
    if (crlfIndex == -1) {
        throw new IllegalArgumentException("End-of-line CRLF sequence not found");
    }

    // Return the index where the CRLF starts
    return crlfIndex;
}

