public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // Add a shutdown hook that attempts to delete the file or directory recursively.
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursively(file);
        } catch (Exception e) {
            // Log the failure; the shutdown hook cannot propagate the exception.
            System.err.println("Failed to delete on exit: " + file);
            e.printStackTrace();
        }
    }));
}

private static void deleteRecursively(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
    }
    if (!f.delete() && f.exists()) {
        throw new IOException("Could not delete file or directory: " + f);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    // Collect files in post-order (children before parent)
    java.util.List<File> files = new java.util.ArrayList<>();
    collect(file, files);
    // Schedule deletion
    for (File f : files) {
        try {
            f.deleteOnExit();
        } catch (SecurityException se) {
            throw new IOException("Failed to schedule deletion of: " + f, se);
        }
    }
}

private static void collect(File f, java.util.List<File> list) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children == null) {
            throw new IOException("Unable to list contents of directory: " + f);
        }
        for (File child : children) {
            collect(child, list);
        }
    }
    list.add(f);
}

