public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    try {
        // If the file does not exist, nothing to schedule
        if (!file.exists()) {
            return;
        }
        // Recursively schedule deletion for all children first
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) {
                    forceDeleteOnExit(child);
                }
            }
        }
        // Schedule this file or directory for deletion on JVM exit
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Cannot register file for deletion: " + e.getMessage(), e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file argument is null");
    }

    // If it is a directory, delete all contents first, then the directory itself.
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files == null) {
            throw new IOException("Unable to list contents of directory: " + file);
        }
        for (File child : files) {
            // Recursive call to handle nested directories
            forceDeleteOnExit(child);
        }
    }
    // Schedule the file (or directory after its contents) for deletion on JVM exit.
    file.deleteOnExit();
}

