public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap cannot be null");
    }
    // Clear existing graph data
    target.removeAllEdges(target.edgeSet());
    target.removeAllVertices(target.vertexSet());
    resultMap.clear();

    // Define partition sizes
    final int leftSize = 3;
    final int rightSize = 3;

    java.util.ArrayList<V> leftVertices = new java.util.ArrayList<>();
    java.util.ArrayList<V> rightVertices = new java.util.ArrayList<>();

    try {
        // Create left partition vertices
        for (int i = 0; i < leftSize; i++) {
            V u = target.addVertex();
            leftVertices.add(u);
            resultMap.put("U" + i, u);
        }

        // Create right partition vertices
        for (int j = 0; j < rightSize; j++) {
            V v = target.addVertex();
            rightVertices.add(v);
            resultMap.put("V" + j, v);
        }

        // Add all possible edges between left and right vertices
        for (V u : leftVertices) {
            for (V v : rightVertices) {
                target.addEdge(u, v);
            }
        }
    } catch (RuntimeException ex) {
        throw new IllegalStateException("Error while generating complete bipartite graph", ex);
    }
}

