    int partitionSize = (resultMap.size() + 1) / 2;
    int counter = 0;
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        if (vertex == null) {
            continue;
        }

        // add vertex to graph if not already present
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }

        // partition vertices into two sets
        if (counter < partitionSize) {
            left.add(vertex);
        } else {
            right.add(vertex);
        }
        counter++;
    }

    // create all edges between the two partitions
    for (V u : left) {
        for (V v : right) {
            try {
                if (!target.containsEdge(u, v)) {
                    target.addEdge(u, v);
                }
            } catch (Exception e) {
                // If an error occurs while adding an edge, skip this pair.
                // The exception is swallowed so that the graph construction can continue.
            }
        }
    }
}

