    }

    int messageSize = schema.getSerializedSize(message);
    int bufSize;
    try {
        bufSize = buffer.getSize();
    } catch (Throwable t) {
        // Fallback to a default size if buffer.size() is unavailable
        bufSize = 4096;
    }

    CodedOutputStream cos = CodedOutputStream.newInstance(out, bufSize);
    cos.writeRawVarint32(messageSize);
    schema.write(message, cos);
    cos.flush();
    return messageSize;
}

