public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Validate inputs
    if (genericType == null || targetType == null) {
        return null;
    }

    // We can only resolve if the genericType is a ParameterizedType
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType pType = (ParameterizedType) genericType;
    Type rawType = pType.getRawType();

    // The raw type must be a Class; otherwise we cannot handle it
    if (!(rawType instanceof Class<?>)) {
        return null;
    }

    Class<?> rawClass = (Class<?>) rawType;

    // If the raw type is not the same as the requested target type, we are not
    // able to resolve generics for this simple implementation
    if (!rawClass.equals(targetType)) {
        return null;
    }

    // Extract the actual type arguments
    Type[] actualTypes = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualTypes.length];

    for (int i = 0; i < actualTypes.length; i++) {
        Type t = actualTypes[i];
        try {
            if (t instanceof Class<?>) {
                result[i] = (Class<?>) t;
            } else if (t instanceof ParameterizedType) {
                // For nested parameterized types, return the raw type
                Type raw = ((ParameterizedType) t).getRawType();
                if (raw instanceof Class<?>) {
                    result[i] = (Class<?>) raw;
                } else {
                    // Unable to resolve this type argument
                    return null;
                }
            } else {
                // Wildcards or type variables cannot be resolved to concrete classes
                return null;
            }
        } catch (ClassCastException e) {
            // In case the cast fails, we cannot resolve the type argument
            return null;
        }
    }

    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (genericType == null || targetType == null) {
            return null;
        }
        // If targetType is not generic, return empty array
        TypeVariable<?>[] targetParams = targetType.getTypeParameters();
        if (targetParams.length == 0) {
            return new Class<?>[0];
        }

        // Map to hold type variable assignments as we walk the hierarchy
        Map<TypeVariable<?>, Type> typeVarAssigns = new HashMap<>();
        if (!collectTypeVarAssignments(typeVarAssigns, genericType, targetType)) {
            // No path found from genericType to targetType
            return null;
        }

        Class<?>[] result = new Class<?>[targetParams.length];
        for (int i = 0; i < targetParams.length; i++) {
            Type resolved = resolveTypeVariable(targetParams[i], typeVarAssigns);
            if (resolved instanceof Class<?>) {
                result[i] = (Class<?>) resolved;
            } else {
                // Could be a TypeVariable or Wildcard that we couldn't resolve to Class
                return null;
            }
        }
        return result;
    } catch (Exception e) {
        // Defensive: any unexpected issue yields null
        return null;
    }
}

private static boolean collectTypeVarAssignments(Map<TypeVariable<?>, Type> map, Type type, Class<?> targetType) {
    if (type == null) {
        return false;
    }

    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pt.getRawType();
        TypeVariable<?>[] vars = raw.getTypeParameters();
        Type[] args = pt.getActualTypeArguments();

        for (int i = 0; i < vars.length; i++) {
            map.put(vars[i], args[i]);
        }

        if (raw.equals(targetType)) {
            return true;
        }

        // Inspect interfaces and super class
        if (searchInInterfacesAndSuperclass(map, raw, targetType)) {
            return true;
        }
    } else if (type instanceof Class) {
        Class<?> clazz = (Class<?>) type;

        if (clazz.equals(targetType)) {
            return true;
        }

        // Inspect interfaces and super class
        if (searchInInterfacesAndSuperclass(map, clazz, targetType)) {
            return true;
        }
    }

    return false;
}

private static boolean searchInInterfacesAndSuperclass(Map<TypeVariable<?>, Type> map, Class<?> clazz, Class<?> targetType) {
    // Interfaces
    for (Type iface : clazz.getGenericInterfaces()) {
        if (collectTypeVarAssignments(map, iface, targetType)) {
            return true;
        }
    }
    // Superclass
    Type superT = clazz.getGenericSuperclass();
    if (superT != null && collectTypeVarAssignments(map, superT, targetType)) {
        return true;
    }
    return false;
}

private static Type resolveTypeVariable(TypeVariable<?> var, Map<TypeVariable<?>, Type> map) {
    Type t = map.get(var);
    Set<Type> visited = new HashSet<>();
    while (t instanceof TypeVariable && map.containsKey(t) && !visited.contains(t)) {
        visited.add(t);
        t = map.get(t);
    }
    return t;
}

