    }
    if (start == end) {
        return new ArrayList<>();
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long step = FETCH_DATA_DURATION;
        if (step <= 0) {
            // If FETCH_DATA_DURATION is not set correctly, fall back to whole remaining range.
            step = remaining;
        } else if (remaining < step) {
            step = remaining;
        }
        long next = current + step;
        // Guard against overflow
        if (next <= current) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

