public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen - len) {
        throw new IndexOutOfBoundsException(
                "index: " + index + ", len: " + len + ", strLen: " + strLen);
    }
    int size = 0;
    final int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1; // 1-byte sequence
        } else if (ch < 0x800) {
            size += 2; // 2-byte sequence
        } else {
            if (Character.isHighSurrogate(ch) && i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4; // 4-byte sequence for supplemental character
                    i++; // skip low surrogate
                } else {
                    // Standalone high surrogate (invalid), encode as 3 bytes
                    size += 3;
                }
            } else {
                // BMP character that does not form a surrogate pair
                size += 3;
            }
        }
        i++;
    }
    return size;
}

