            size += 1;
        } else if (ch <= 0x07FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && (i + 1) < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Surrogate pair forms a code point requiring 4 bytes
            size += 4;
            i++; // skip low surrogate
        } else {
            // All other BMP characters (including lone surrogates) are 3 bytes in UTF-8
            size += 3;
        }
    }
    return size;
}

