private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is not initialized");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is not initialized");
    }
    final int frameSize = currentFrame.size();
    if (start < 0 || end > frameSize) {
        throw new IndexOutOfBoundsException(
            "start (" + start + ") or end (" + end + ") out of range (0, " + frameSize + ")");
    }
    if (start > end) {
        throw new IllegalArgumentException(
            "start index (" + start + ") is greater than end index (" + end + ")");
    }

    for (int i = start; i < end; i++) {
        Object entry = currentFrame.get(i);
        if (entry == null) {
            // ITEM_Top (tag 0)
            stackMapTableEntries.write(0);
            continue;
        }

        try {
            if (entry instanceof AbstractType) {
                byte[] encoded = ((AbstractType) entry).toVerificationTypeInfo();
                stackMapTableEntries.write(encoded, 0, encoded.length);
            } else if (entry instanceof Integer) {
                // ITEM_Integer (tag 1)
                stackMapTableEntries.write(1);
            } else if (entry instanceof Float) {
                // ITEM_Float (tag 2)
                stackMapTableEntries.write(2);
            } else if (entry instanceof Double) {
                // ITEM_Double (tag 3)
                stackMapTableEntries.write(3);
            } else if (entry instanceof Long) {
                // ITEM_Long (tag 4)
                stackMapTableEntries.write(4);
            } else if (entry instanceof String) {
                // ITEM_Object (tag 7) – placeholder, actual constant-pool index resolution
                // must be handled by the caller. Here we write only the tag.
                stackMapTableEntries.write(7);
                // TODO: append the constant-pool index of the class type
            } else if (entry instanceof UninitializedInfo) {
                // ITEM_Uninitialized (tag 8) – also a placeholder
                stackMapTableEntries.write(8);
                // TODO: append offset of the uninitialized object
            } else {
                throw new IllegalArgumentException(
                    "Unsupported type for stack map entry at index " + i + ": " + entry.getClass().getName());
            }
        } catch (Exception e) {
            throw new IllegalStateException(
                "Failed to encode stack map entry at index " + i, e);
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    // Validate parameters
    if (start < 0 || end < start || end > currentFrame.length) {
        throw new IllegalArgumentException(
                "Invalid range: start=" + start + ", end=" + end + ", frame length=" + currentFrame.length);
    }

    try {
        for (int i = start; i < end; i++) {
            AbstractType at = currentFrame[i];
            int tag = at.getTag();

            switch (tag) {
                // Primitive and special types: TAG + no extra data
                case AbstractType.TOP:
                case AbstractType.INTEGER:
                case AbstractType.FLOAT:
                case AbstractType.DOUBLE:
                case AbstractType.LONG:
                case AbstractType.NULL:
                case AbstractType.UNINITIALIZED_THIS:
                    stackMapTableEntries.writeByte(tag);
                    break;

                // OBJECT: TAG + u2 cpool_index
                case AbstractType.OBJECT:
                    stackMapTableEntries.writeByte(tag);
                    stackMapTableEntries.writeShort(at.getCpoolIndex());
                    break;

                // UNINITIALIZED: TAG + u2 offset
                case AbstractType.UNINITIALIZED:
                    stackMapTableEntries.writeByte(tag);
                    stackMapTableEntries.writeShort(at.getOffset());
                    break;

                default:
                    throw new IllegalStateException("Unknown verification_type_info tag: " + tag);
            }
        }
    } catch (java.io.IOException e) {
        throw new RuntimeException("Failed to write abstract types to StackMapTable", e);
    }
}

