        CharSequence seq = (CharSequence) value;
        if (seq.length() == 0) {
            throw new IllegalArgumentException("Cannot convert empty string to Character");
        }
        if (seq.length() > 1) {
            throw new IllegalArgumentException("String length > 1 cannot be converted to Character");
        }
        return Character.valueOf(seq.charAt(0));
    }

    // Number: cast to char based on int value
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }

    // byte[] with a single byte (treated as char)
    if (value instanceof byte[]) {
        byte[] bytes = (byte[]) value;
        if (bytes.length != 1) {
            throw new IllegalArgumentException("Byte array length must be 1 to convert to Character");
        }
        return Character.valueOf((char) bytes[0]);
    }

    // char[] with a single char
    if (value instanceof char[]) {
        char[] chars = (char[]) value;
        if (chars.length != 1) {
            throw new IllegalArgumentException("Char array length must be 1 to convert to Character");
        }
        return Character.valueOf(chars[0]);
    }

    // Attempt using toString() if it yields a single character
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    }

    // If none of the above, conversion cannot be performed
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character (or char primitive)
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }

    // Null values are returned as null
    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // Numeric values can be converted to char if within range
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue < Character.MIN_VALUE || intValue > Character.MAX_VALUE) {
            throw new IllegalArgumentException(
                "Numeric value out of character range: " + intValue
            );
        }
        return (char) intValue;
    }

    // Single-character string
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        }
        throw new IllegalArgumentException(
            "String must be a single character but was: \"" + s + "\""
        );
    }

    // Unsupported type
    throw new IllegalArgumentException(
        "Cannot convert type " + value.getClass() + " to Character"
    );
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (value == null) {
        return null;
    }
    if (Character.class.equals(type) || char.class.equals(type)) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            }
            throw new Exception("Cannot convert String of length > 1 to Character");
        }
        if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        }
        // Fallback: try string representation if it yields a single character
        String repr = value.toString();
        if (repr.length() == 1) {
            return repr.charAt(0);
        }
        throw new Exception("Cannot convert value to Character: " + value);
    }
    throw new Exception("Unsupported target type for conversion: " + type.getName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!(type == Character.class || type == char.class)) {
        throw new Exception("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }

    if (value instanceof Character) {
        return value;
    }

    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return Character.valueOf(cs.charAt(0));
        }
        throw new Exception(
                "String length must be 1 to convert to Character, got length=" + cs.length());
    }

    if (value instanceof Number) {
        return Character.valueOf((char) ((Number) value).intValue());
    }

    if (value instanceof Boolean) {
        return Character.valueOf(((Boolean) value).booleanValue() ? 't' : 'f');
    }

    if (value instanceof Enum) {
        String name = ((Enum<?>) value).name();
        if (name.length() == 1) {
            return Character.valueOf(name.charAt(0));
        }
    }

    throw new Exception(
            "Cannot convert a value of type " + value.getClass().getName() + " to java.lang.Character");
}

