public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }

    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }

    int upperLimit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        try {
            upperLimit = Math.addExact(desiredCapacity, (int) Math.floor(desiredCapacity * 0.11));
        } catch (ArithmeticException e) {
            upperLimit = Integer.MAX_VALUE;
        }
    }

    while (candidate <= upperLimit) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }

    // If no prime found within the 11% tolerance, keep searching beyond it
    while (candidate < Integer.MAX_VALUE) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid overflow when adding 2
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }

    // Fallback: if all else fails (should not happen for typical input ranges)
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true; // 2 and 3 are prime
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    int limit = (int) Math.sqrt(n);
    for (int i = 5; i <= limit; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

