private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    int i = 5;
    int w = 2;
    int sqrtN = (int)Math.sqrt(n);
    while (i <= sqrtN) {
        if (n % i == 0) {
            return false;
        }
        i += w;
        w = 6 - w;
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    // Return 2 for any capacity <= 2
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start with the desired capacity, adjusting for odd numbers (2 is prime, all others can be odd)
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Search forward for the next prime
    while (candidate > 0) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Increment by 2 to stay on odd numbers
        if (candidate <= Integer.MAX_VALUE - 2) {
            candidate += 2;
        } else {
            // We reached the upper bound of integer without finding a prime
            // Return the largest possible value (though it will not be prime)
            return Integer.MAX_VALUE;
        }
    }
    // In theory unreachable, but satisfies compiler
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n == 2) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrtN; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    int candidate = Math.max(2, desiredCapacity);
    if (candidate == 2) {
        return 2;
    }
    // Ensure candidate is odd
    if ((candidate & 1) == 0) {
        candidate++;
    }
    // Search for the next prime
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Prevent integer overflow
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("No prime could be found within int range");
        }
        candidate += 2; // Skip even numbers
    }
}

private static boolean isPrime(int n) {
    if (n < 2) {
        return false;
    }
    if (n == 2 || n == 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }

    // Handle low numbers directly
    if (desiredCapacity <= 2) {
        return 2;
    }

    int candidate = desiredCapacity;
    // Make it odd if it's even
    if ((candidate & 1) == 0) {
        candidate++;
    }

    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // Skip even numbers
        // Protect against integer overflow
        if (candidate <= 0) {
            throw new RuntimeException("Overflow while searching for next prime");
        }
    }
}

private static boolean isPrime(int n) {
    if (n < 2) {
        return false;
    }
    if (n == 2 || n == 3) {
        return true;
    }
    if ((n & 1) == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrtN; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

