public static Object findFirstMatch(Collection source, Collection candidates) {
    // Handle null arguments
    if (source == null || candidates == null) {
        return null;
    }
    // Iterate over each candidate and return the first that exists in source
    for (Object candidate : candidates) {
        try {
            if (source.contains(candidate)) {
                return candidate;
            }
        } catch (RuntimeException e) {
            // If source.contains throws a runtime exception, skip this candidate and continue
            continue;
        }
    }
    // No match found
    return null;
}

