@Override public String readString() throws IOException {
    // Read the length prefix (assumed to be a signed 4‑byte integer).
    int length = readInt();
    // Negative length code indicates a null string value.
    if (length < 0) {
        return null;
    }
    // Read 'length' bytes from the input stream.
    byte[] bytes = new byte[length];
    readFully(bytes);
    // Convert the raw bytes to a UTF‑8 string.
    return new String(bytes, "UTF-8");
}

@Override public String readString() throws IOException {
    int length = in.readInt();
    if (length == -1) {
        return null;
    }
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    byte[] bytes = new byte[length];
    in.readFully(bytes);
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

@Override public String readString() throws IOException {
    // Read an unsigned short (16‑bit) length prefix
    int length = readUnsignedShort();
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    // Allocate byte array for the string data
    byte[] bytes = new byte[length];
    // Read the exact number of bytes; this method throws EOFException if insufficient data
    readFully(bytes);
    // Construct the string using UTF‑8 encoding
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

@Override
public String readString() throws IOException {
    // Read the length prefix (int). A negative length (e.g., -1) represents a null string.
    int length;
    try {
        length = in.readInt();
    } catch (IOException e) {
        throw new IOException("Failed to read string length", e);
    }

    if (length == -1) {
        return null; // Indicates a null string value.
    }
    if (length == 0) {
        return "";    // Empty string representation.
    }

    if (length < 0) {
        throw new IOException("Invalid string length: " + length);
    }

    byte[] bytes = new byte[length];
    int readBytes = 0;
    while (readBytes < length) {
        int count = in.read(bytes, readBytes, length - readBytes);
        if (count == -1) {
            throw new IOException("Unexpected end of stream while reading string data");
        }
        readBytes += count;
    }

    try {
        return new String(bytes, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new IOException("UTF-8 encoding is not supported", e);
    }
}

@Override
public String readString() throws IOException {
    // Read an unsigned short length prefix and then the UTF-8 encoded bytes
    int length = in.readUnsignedShort();  // length must be non-negative and <= 65535
    byte[] bytes = new byte[length];
    if (length > 0) {
        in.readFully(bytes);
    }
    // Convert to String using UTF-8 encoding; UnsupportedEncodingException
    // is a subclass of IOException so it propagates correctly.
    return new String(bytes, "UTF-8");
}

private static int digitValue(final char c){
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'a' && c <= 'z') {
