                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape: \\u" + hex);
                    }
                    i += 4;
                    break;
                default:
                    if (next >= '0' && next <= '7') { // octal escape
                        int j = i;
                        int oct = next - '0';
                        // read up to two more octal digits
                        while (j < i + 2 && j + 1 < chars.length) {
                            char d = chars[++j];
                            if (d >= '0' && d <= '7') {
                                oct = (oct << 3) + (d - '0');
                            } else {
