                            }
                        }
                        sb.append((char) oct);
                        i = j;
                    } else {
                        // Invalid escape sequence
                        throw new Exception("Invalid escape sequence: \\" + next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
