public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // c is '\\'
        i++; // move past backslash
        if (i == len) {
            // trailing backslash, keep it
            sb.append('\\');
            break;
        }
        char next = str.charAt(i);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                // Unicode escape: \uXXXX
                i++; // skip 'u'
                int hexStart = i;
                int hexEnd = Math.min(len, hexStart + 4);
                if (hexEnd - hexStart < 4) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + (i - 2));
                }
                String hex = str.substring(hexStart, hexEnd);
                try {
                    int value = Integer.parseInt(hex, 16);
                    sb.append((char) value);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + (i - 2));
                }
                i = hexEnd;
                break;
            default:
                // Octal escape or non-standard escape
                if (next >= '0' && next <= '7') {
                    int octal = next - '0';
                    i++;
                    // second octal digit
                    if (i < len) {
                        char d2 = str.charAt(i);
                        if (d2 >= '0' && d2 <= '7') {
                            octal = octal * 8 + (d2 - '0');
                            i++;
                            // third octal digit
                            if (i < len) {
                                char d3 = str.charAt(i);
                                if (d3 >= '0' && d3 <= '7') {
                                    octal = octal * 8 + (d3 - '0');
                                    i++;
                                }
                            }
                        }
                    }
                    sb.append((char) octal);
                } else {
                    // For any other character following a backslash, just append it
                    sb.append(next);
                    i++;
                }
                break;
        }
    }
    return sb.toString();
}

