private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        // If either input set is null, return an empty set as intersection cannot be computed
        return new HashSet<>();
    }

    if (set1.isEmpty() || set2.isEmpty()) {
        // If either set is empty, intersection is empty
        return new HashSet<>();
    }

    // Select the smaller set for iteration to minimize lookups
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() > set2.size() ? set1 : set2;

    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }

    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2){
    try {
        if (set1 == null || set2 == null) {
            return java.util.Collections.emptySet();
        }
        // pick the smaller set to iterate over
        Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
        Set<V> larger  = set1.size() > set2.size() ? set1 : set2;
        Set<V> result = new java.util.HashSet<>(smaller);
        result.retainAll(larger);
        return result;
    } catch (IllegalArgumentException | NullPointerException | java.util.ConcurrentModificationException e) {
        // In case of unexpected runtime problems return an empty set rather than propagating the exception
        return java.util.Collections.emptySet();
    }
}

