protected int removeUnusedNodes() {
    int removedCount = 0;
    if (root == null) {
        return 0;
    }
    java.util.Queue<CategoryNode> queue = new java.util.LinkedList<>();
    queue.add(root);
    while (!queue.isEmpty()) {
        CategoryNode current = queue.poll();
        if (!current.isActive()) {
            CategoryNode parent = current.getParent();
            if (parent != null) {
                parent.getChildren().remove(current);
            } else { // current is root
                root = null;
            }
            removedCount++;
            continue; // skip its children
        }
        java.util.List<CategoryNode> children = current.getChildren();
        if (children != null) {
            for (CategoryNode child : children) {
                queue.add(child);
            }
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume the tree has a field named 'root' of type Category that represents the tree's root.
        if (root == null) {
            return 0;
        }

        // Use a stack to perform an iterative depth‑first traversal.
        java.util.Stack<Category> stack = new java.util.Stack<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            Category current = stack.pop();

            // Iterate over the current node's children.
            java.util.Iterator<Category> it = current.getChildren().iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    // Remove inactive child and increment counter.
                    it.remove();
                    removedCount++;
                } else {
                    // Keep the node and traverse its children later.
                    stack.push(child);
                }
            }
        }
    } catch (Exception ex) {
        // Exception handling – log if a logger is available, otherwise swallow silently.
        // Example: Logger.getLogger(getClass().getName()).log(Level.SEVERE, null, ex);
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    try {
        // If the entire tree is empty, nothing to remove
        if (root == null) {
            return 0;
        }

        // If the root itself is inactive, remove the whole tree
        if (!root.isActive()) {
            root = null;
            return 1;
        }

        // Recursively prune inactive children of the root
        return pruneChildren(root.getChildren());
    } catch (Exception e) {
        // In case of any unexpected error, do not remove anything
        return 0;
    }
}

private int pruneChildren(java.util.List<Category> children) {
    if (children == null) {
        return 0;
    }

    int removedCount = 0;
    java.util.Iterator<Category> iterator = children.iterator();

    while (iterator.hasNext()) {
        Category child = iterator.next();
        if (child == null) {
            continue;
        }

        if (!child.isActive()) {
            // Remove inactive node from its parent
            iterator.remove();
            removedCount++;
        } else {
            // Recursively prune this child's own descendants
            removedCount += pruneChildren(child.getChildren());
        }
    }

    return removedCount;
}

protected int removeUnusedNodes() {
    // If the tree root is null, nothing to remove
    if (root == null) {
        return 0;
    }

    int removed = 0;
    try {
        // If the root itself is inactive, remove the entire tree
        if (!root.isActive()) {
            removed = countSubtreeNodes(root);
            root = null;
            return removed;
        }

        // Otherwise, recursively remove inactive sub‑nodes from each child
        java.util.List<Category> children = root.getChildren();
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            removed += removeFromParent(root, child);
        }
    } catch (Exception e) {
        // In case of any unexpected error, log or rethrow as needed
        // For safety, we simply return the number removed so far
    }
    return removed;
}

private int removeFromParent(Category parent, Category node) {
    if (!node.isActive()) {
        // Count all nodes in this subtree and remove it from its parent
        int count = countSubtreeNodes(node);
        parent.getChildren().remove(node);
        return count;
    }

    int removed = 0;
    java.util.List<Category> children = node.getChildren();
    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        removed += removeFromParent(node, child);
    }
    return removed;
}

private int countSubtreeNodes(Category node) {
    int count = 1; // count this node
    java.util.List<Category> children = node.getChildren();
    for (Category child : children) {
        count += countSubtreeNodes(child);
    }
    return count;
}

protected int removeUnusedNodes() {
    try {
        // Assume the tree root is stored in a field named 'root'
        if (root == null) {
            return 0;
        }

        // If the root itself is inactive, remove the entire tree
        if (!root.isActive()) {
            int removed = countSubtreeNodes(root);
            root = null;
            return removed;
        }

        return pruneChildren(root);
    } catch (Exception e) {
        // Gracefully handle any runtime issues
        return 0;
    }
}

private int pruneChildren(Category node) {
    int removed = 0;
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }

    // Iterate backwards to safely remove while iterating
    for (int i = children.size() - 1; i >= 0; i--) {
        Category child = children.get(i);
        try {
            if (!child.isActive()) {
                // Count all nodes in this subtree
                removed += countSubtreeNodes(child);
                children.remove(i);
            } else {
                removed += pruneChildren(child);
            }
        } catch (Exception inner) {
            // If a child throws an exception, skip it but continue processing others
            continue;
        }
    }

    return removed;
}

private int countSubtreeNodes(Category node) {
    int count = 1; // count the node itself
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += countSubtreeNodes(child);
        }
    }
    return count;
}

