final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Basic safety checks
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("Constant pool indexes are 1-based and must be > 0");
    }

    // Determine the start offset of the requested constant pool entry.
    // This helper is assumed to exist in the surrounding class.
    final int cpEntryStart = getConstantPoolEntryStart(constantPoolEntryIndex);
    if (cpEntryStart < 0 || cpEntryStart + 3 > classFileBuffer.length) {
        throw new IndexOutOfBoundsException("Invalid constant pool entry offset");
    }

    // The entry format for CONSTANT_Utf8:
    //   tag (1 byte) => should be 1, but we trust the caller
    //   length (2 bytes, big‑endian)
    //   UTF‑8 bytes (length)
    final int length = ((classFileBuffer[cpEntryStart + 1] & 0xFF) << 8)
                     |  (classFileBuffer[cpEntryStart + 2] & 0xFF);

    if (length < 0 || cpEntryStart + 3 + length > classFileBuffer.length) {
        throw new IndexOutOfBoundsException("UTF‑8 string length extends beyond class file");
    }

    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Provided char buffer is too small for UTF‑8 string");
    }

    // Copy the raw UTF‑8 bytes into a temporary array.
    final byte[] bytes = new byte[length];
    System.arraycopy(classFileBuffer, cpEntryStart + 3, bytes, 0, length);

    // Decode the UTF‑8 bytes into a Java String.
    // Using the standard charset guarantees the method will never throw.
    final String utf8String = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);

    // Copy the decoded characters into the supplied buffer for potential reuse.
    for (int i = 0; i < utf8String.length(); i++) {
        charBuffer[i] = utf8String.charAt(i);
    }

    return utf8String;
}

