private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Basic argument validation
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    // direction is expected to be either 1 (clockwise) or -1 (counter‑clockwise)
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 or -1");
    }

    // Create an initial circulator starting at the given node and direction.
    // The actual way to obtain a circulator depends on the surrounding code.
    // We assume the Node class provides a method to obtain an OuterFaceCirculator.
    OuterFaceCirculator circ = start.getOuterFaceCirculator(dir);
    if (circ == null) {
        // If we cannot create a circulator we simply return null.
        return null;
    }

    // Use a set to guard against wrapping around without finding the stop node.
    java.util.Set<Node> visited = new java.util.HashSet<>();

    while (!circ.node().equals(stop) && !predicate.test(circ.node())) {
        // If we revisit a node we are in a loop that cannot reach the stop node.
        if (!visited.add(circ.node())) {
            break;
        }
        // Advance the circulator. We expect a method that moves in the given direction
        // and returns the new circulator; if the traversal ends we break.
        circ = circ.advance(dir);
        if (circ == null) {
            break;
        }
    }

    // At this point circ points either to the node satisfying the predicate or to the stop node.
    return circ;
}

