private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes cannot be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    final Node firstNode = start;
    boolean firstIteration = true;

    while (circ != null) {
        Node current = circ.getNode();
        if (current == null) {
            break; // safety guard
        }
        // If the current node satisfies the predicate, return it.
        if (predicate.test(current)) {
            return circ;
        }
        // If we reached the stop node, return it even if predicate not met.
        if (current == stop) {
            return circ;
        }

        // Advance to the next node in the cycle.
        circ = circ.next();

        // If we have looped back to the start after the first iteration,
        // the stop node was not found; return a circulator positioned at stop.
        if (!firstIteration && circ != null && circ.getNode() == firstNode) {
            return new OuterFaceCirculator(stop, dir);
        }
        firstIteration = false;
    }

    // Fallback: if the loop exits unexpectedly, return a circulator at the stop node.
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Defensive checks
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }

    // Create a circulator positioned at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // Move one step in the requested direction before starting search.
    // We assume dir > 0 means forward (next), dir <= 0 means backward (prev).
    // If direction is ambiguous, default to forward.
    if (dir > 0) {
        circ.next();
    } else if (dir < 0) {
        circ.prev();
    }

    // Traverse until we reach the stop node or find a match.
    try {
        while (!circ.current().equals(stop) && !predicate.test(circ.current())) {
            // Advance one step
            if (dir > 0) {
                circ.next();
            } else {
                circ.prev();
            }
        }
    } catch (Exception e) {
        // In case of any unexpected issues (e.g., broken links), return the stop circulator.
        return new OuterFaceCirculator(stop);
    }

    // Return the circulator pointing to the node that satisfied the predicate
    // or the stop node if no match was found.
    return circ;
}

