        if (idx > max) {
            max = idx;
        }
    }

    // Continuous indices must fill the whole range from min to max without gaps.
    if (max - min + 1 != indices.length) {
        throw new IllegalStateException(
            "Sharding key indices for model " + modelName + " are not continuous: expected indices "
            + min + " to " + max + " but found gaps.");
    }
