    if (matrix == null) {
        throw new IllegalStateException("Matrix data is not initialized");
    }
    if (row < 0 || row >= matrix.length) {
        throw new IndexOutOfBoundsException("Row index out of bounds: " + row);
    }
    int count = 0;
    try {
        for (int val : matrix[row]) {
            if (val != 0) {
                count++;
            }
        }
    } catch (Exception e) {
        // Unexpected runtime error during iteration
        throw new RuntimeException("Failed to count non-zero entries in row " + row, e);
    }
    return count;
}

