public byte[] toByteArray() {
    try {
        if (buf == null || count <= 0) {
            return new byte[0];
        }
        int len = Math.min(count, buf.length);
        byte[] result = new byte[len];
        System.arraycopy(buf, 0, result, 0, len);
        return result;
    } catch (Exception e) {
        throw new IllegalStateException("Error copying byte array", e);
    }
}

public byte[] toByteArray(){
    if (buf == null) {
        return new byte[0];
    }
    int size = count;
    if (size < 0) {
        size = 0;
    }
    return java.util.Arrays.copyOf(buf, size);
}

public byte[] toByteArray() {
    /* 
     * This method returns a copy of the data currently stored in the internal buffer.
     * It assumes that the class has two protected fields:
     *   byte[] buf;   // the underlying storage array
     *   int count;    // the number of valid bytes in buf
     * 
     * Defensive checks are performed to catch any unexpected corruption of the internal
     * state.  If the state is invalid, an IllegalStateException is thrown.
     */
    if (buf == null) {
        throw new IllegalStateException("Internal buffer is null");
    }
    if (count < 0 || count > buf.length) {
        throw new IllegalStateException("Internal buffer size (" + buf.length +
                                        ") is inconsistent with count (" + count + ")");
    }

    byte[] result = new byte[count];
    System.arraycopy(buf, 0, result, 0, count);
    return result;
}

public byte[] toByteArray() {
    try {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int read;
        while ((read = this.in.read(buffer)) != -1) {
            baos.write(buffer, 0, read);
        }
        return baos.toByteArray();
    } catch (IOException e) {
        throw new RuntimeException("Error converting stream to byte array", e);
    }
}

public byte[] toByteArray() {
    if (buffer == null) {
        return new byte[0];
    }
    byte[] copy = new byte[count];
    System.arraycopy(buffer, 0, copy, 0, count);
    return copy;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    // Validate inputs
    if (tour == null) {
        throw new IllegalArgumentException("The tour set must not be null.");
    }
    if (graph == null) {
        throw new IllegalArgumentException("The graph must not be null.");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("The tour set must not be empty.");
    }

    // Ensure all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not present in the graph.");
        }
    }

    // Build an adjacency map and verify that each vertex has degree 2 within the tour (cycle condition)
    Map<V, List<E>> adjacency = new HashMap<>();
    Map<V, Integer> degree = new HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
        degree.merge(source, 1, Integer::sum);
        degree.merge(target, 1, Integer::sum);
    }
    for (Map.Entry<V,Integer> entry : degree.entrySet()) {
        if (!entry.getValue().equals(2)) {
            throw new IllegalArgumentException(
                "The provided edge set does not represent a cycle (vertex " + entry.getKey() + " has degree " + entry.getValue() + ").");
        }
    }

    // Choose arbitrary start vertex
    V startVertex = null;
    for (V v : adjacency.keySet()) {
        startVertex = v;
        break;
    }
    if (startVertex == null) {
        throw new IllegalStateException("Unable to determine start vertex.");
    }

    // Reconstruct the tour in order
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    V current = startVertex;
    vertexList.add(current);
    while (visitedEdges.size() < tour.size()) {
        List<E> adjEdges = adjacency.get(current);
        if (adjEdges == null) {
            throw new IllegalStateException("No adjacent edges found for vertex " + current);
        }
        E nextEdge = null;
        for (E e : adjEdges) {
            if (!visitedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalStateException("Unable to find the next edge in the tour from vertex " + current);
        }

        visitedEdges.add(nextEdge);
        edgeList.add(nextEdge);

        // Determine the opposite vertex
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        V opposite = current.equals(source) ? target : source;
        current = opposite;
        vertexList.add(current);
    }

    // The tour should end at the starting vertex
    if (!current.equals(startVertex)) {
        throw new IllegalStateException("The reconstructed tour does not form a cycle; ended at vertex " + current + " instead of starting vertex " + startVertex);
    }

    // Compute the total weight
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    try {
        return new GraphWalk<>(graph, vertexList.get(0), current, totalWeight, vertexList, edgeList);
    } catch (Exception e) {
        throw new RuntimeException("Failed to create GraphPath from the given edge set.", e);
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (graph == null || tour == null) {
        throw new IllegalArgumentException("Graph and tour must not be null.");
    }
    // Empty tour yields an empty path
    if (tour.isEmpty()) {
        List<V> emptyVertices = new ArrayList<>();
        List<E> emptyEdges = new ArrayList<>();
        return new org.jgrapht.graph.SimpleGraphPath<>(graph,
                null, null, emptyVertices, emptyEdges, 0.0);
    }

    // Copy edges to avoid modifying the caller's set
    Set<E> remaining = new HashSet<>(tour);

    // Pick an arbitrary starting edge
    E startEdge = remaining.iterator().next();
    if (!graph.containsEdge(startEdge)) {
        throw new IllegalArgumentException("Edge set contains an edge not present in the graph.");
    }

    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;

    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    double totalWeight = 0.0;

    // Build the path by following incident unused edges
    while (!remaining.isEmpty()) {
        E chosen = null;
        for (E e : remaining) {
            if (!graph.containsEdge(e)) {
                throw new IllegalArgumentException("Edge set contains an edge not present in the graph.");
            }
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) || tgt.equals(currentVertex)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            throw new IllegalArgumentException("Provided set of edges does not form a continuous tour.");
        }

        remaining.remove(chosen);
        edgeList.add(chosen);
        totalWeight += graph.getEdgeWeight(chosen);

        V nextVertex = graph.getEdgeSource(chosen).equals(currentVertex)
                       ? graph.getEdgeTarget(chosen)
                       : graph.getEdgeSource(chosen);
        vertexList.add(nextVertex);
        currentVertex = nextVertex;
    }

    // The tour should return to the start vertex
    if (!currentVertex.equals(startVertex)) {
        throw new IllegalArgumentException("Provided set of edges does not form a closed tour.");
    }

    return new org.jgrapht.graph.SimpleGraphPath<>(graph,
            startVertex, currentVertex, vertexList, edgeList, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the provided graph");
        }
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }

    // Determine start and end vertices
    V start = null;
    V end = null;
    int startCandidates = 0;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        int degree = entry.getValue().size();
        if (degree == 1) {
            if (start == null) {
                start = entry.getKey();
            } else {
                end = entry.getKey();
            }
            startCandidates++;
        }
    }
    if (startCandidates > 2) {
        throw new IllegalArgumentException("The edge set cannot form a simple path (too many degree‑1 vertices)");
    }
    if (startCandidates == 0) { // cycle
        Iterator<V> it = adjacency.keySet().iterator();
        if (it.hasNext()) {
            start = it.next();
        }
    }
    if (start == null) {
        throw new IllegalArgumentException("No valid start vertex found");
    }

    // Build ordered list of edges
    List<E> orderedEdges = new ArrayList<>(tour.size());
    Set<E> usedEdges = new HashSet<>();
    V current = start;
    while (orderedEdges.size() < tour.size()) {
        List<E> adjEdges = adjacency.get(current);
        if (adjEdges == null || adjEdges.isEmpty()) {
            throw new IllegalArgumentException("Disconnected graph component encountered");
        }
        E nextEdge = null;
        for (E e : adjEdges) {
            if (!usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Unable to extend path from vertex " + current);
        }
        orderedEdges.add(nextEdge);
        usedEdges.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                       ? graph.getEdgeTarget(nextEdge)
                       : graph.getEdgeSource(nextEdge);
        current = nextVertex;
    }

    end = current;
    return new DefaultGraphPath<>(graph, start, end, orderedEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null){
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()){
        return null;
    }
    List<E> orderedEdges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // Start with an arbitrary edge
    E startEdge = remaining.iterator().next();
    remaining.remove(startEdge);
    orderedEdges.add(startEdge);

    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);

    // Map each vertex to the edges incident to it
    Map<V, List<E>> vertexEdges = new HashMap<>();
    for (E e : tour){
        V s = graph.getEdgeSource(e);
        V t = graph.getEdgeTarget(e);
        vertexEdges.computeIfAbsent(s, k -> new ArrayList<>()).add(e);
        vertexEdges.computeIfAbsent(t, k -> new ArrayList<>()).add(e);
    }

    while (!remaining.isEmpty()){
        E nextEdge = null;
        List<E> candidates = vertexEdges.getOrDefault(currentVertex, Collections.emptyList());
        for (E e : candidates){
            if (!remaining.contains(e)){
                continue;
            }
            // For directed graphs we need to respect the direction
            try{
                if (graph.getType().isDirected()){
                    if (!graph.getEdgeSource(e).equals(currentVertex)){
                        continue;
                    }
                }
            }catch (NoSuchMethodError | UnsupportedOperationException ignored){
                // If getType() or isDirected() is not available, fall back to undirected handling
            }
            nextEdge = e;
            break;
        }
        if (nextEdge == null){
            return null; // cannot extend path
        }

        orderedEdges.add(nextEdge);
        remaining.remove(nextEdge);

        V s = graph.getEdgeSource(nextEdge);
        V t = graph.getEdgeTarget(nextEdge);
        currentVertex = currentVertex.equals(s) ? t : s;
    }

    double totalWeight = 0.0;
    for (E e : orderedEdges){
        totalWeight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, startVertex, currentVertex, totalWeight, orderedEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null) {
        throw new IllegalArgumentException("Tour set must not be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set must contain at least one edge");
    }

    // Verify that all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not contained in the supplied graph");
        }
    }

    // Build a degree map to ensure each vertex has degree 2 in the tour
    Map<V, Integer> degree = new java.util.HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        degree.put(src, degree.getOrDefault(src, 0) + 1);
        degree.put(tgt, degree.getOrDefault(tgt, 0) + 1);
    }
    for (java.util.Map.Entry<V, Integer> entry : degree.entrySet()) {
        if (entry.getValue() != 2) {
            throw new IllegalArgumentException("Vertex " + entry.getKey() + " has degree " + entry.getValue() + " in the tour, expected 2");
        }
    }

    // Build adjacency list of edges per vertex
    Map<V, java.util.List<E>> adj = new java.util.HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new java.util.ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new java.util.ArrayList<>()).add(e);
    }

    // Start traversal from an arbitrary vertex
    E firstEdge = tour.iterator().next();
    V current = graph.getEdgeSource(firstEdge);
    V startVertex = current;

    java.util.Set<E> visited = new java.util.HashSet<>();
    java.util.List<E> ordered = new java.util.ArrayList<>();

    while (visited.size() < tour.size()) {
        java.util.List<E> edgesAt = adj.get(current);
        if (edgesAt == null || edgesAt.isEmpty()) {
            throw new IllegalStateException("No edges available at vertex " + current);
        }
        E nextEdge = null;
        for (E e : edgesAt) {
            if (!visited.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalStateException("Encountered a vertex with all incident edges already visited before tour is complete");
        }
        visited.add(nextEdge);
        ordered.add(nextEdge);

        // Move to the other vertex of the edge
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                       ? graph.getEdgeTarget(nextEdge)
                       : graph.getEdgeSource(nextEdge);
        current = nextVertex;
    }

    V endVertex = current;

    // Compute total weight of the tour
    double totalWeight = 0.0;
    for (E e : ordered) {
        totalWeight += graph.getEdgeWeight(e);
    }

    return new GraphWalk<>(graph, startVertex, endVertex, ordered, totalWeight);
}

