int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    // Simple key combining name and descriptor
    String key = name + '\u0000' + descriptor;
    Integer existing = constantPoolIndexMap.get(key);
    if(existing != null){
        return existing;
    }
    // Local representation of CONSTANT_NameAndType_info
    class ConstantNameAndTypeInfo{
        final String n;
        final String d;
        ConstantNameAndTypeInfo(String n, String d){ this.n = n; this.d = d; }
    }
    ConstantNameAndTypeInfo info = new ConstantNameAndTypeInfo(name, descriptor);
    int idx = constantPool.size();
    constantPool.add(info);
    constantPoolIndexMap.put(key, idx);
    return idx;
}

int addConstantNameAndType(final String name, final String descriptor){
    try {
        if (name == null || descriptor == null) {
            throw new IllegalArgumentException("Name and descriptor cannot be null");
        }

        /* 
