            bucketsByLabel.set(0, new HashSet<>());
        }
    }

    Set<Integer> sourceSet = bucketsByLabel.get(minLabel);
    if (sourceSet == null || sourceSet.isEmpty()) {
        return; // nothing to move
    }

    Set<Integer> targetSet = bucketsByLabel.get(0);
    if (targetSet == null) {
        targetSet = new HashSet<>();
        bucketsByLabel.set(0, targetSet);
    }

    for (int v : sourceSet) {
        if (v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException(
                    "Vertex index " + v + " is out of bounds for labels list");
        }
        labels.set(v, 0);
        targetSet.add(v);
    }
    sourceSet.clear();
}

