public static int countOccurrencesOf(String str, String sub) {
    // Handle null inputs as specified
    if (str == null || sub == null) {
        return 0;
    }

    // Avoid infinite loop: an empty substring would match at every position.
    // We choose to return 0 for an empty pattern (common defensive choice).
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index += sub.length(); // Move past the last matched occurrence
    }
    return count;
}

