private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    // Iterate over the source list's nodes using its sentinel nodes
    ListNode<E> node = list.head.next;
    while (node != list.tail) {
        // Keep reference to the next node before moving `node`
        ListNode<E> nextNode = node.next;
        // Remove 'node' from the source list
        list.removeListNode(node);
        // Add 'node' to the current list
        this.addListNode(node);
        // Advance to the next node in the original list
        node = nextNode;
    }
}

