    }

    // If the source list is empty, nothing to do.
    if (list.size == 0) {
        return;
    }

    // Obtain the first and last nodes of the source list.
    ListNodeImpl<E> sourceFirst = list.firstNode;
    ListNodeImpl<E> sourceLast = list.lastNode;

    // Link the source nodes to the destination list.
    if (this.firstNode == null) {
        // Destination list is empty; take ownership of the source nodes.
        this.firstNode = sourceFirst;
        this.lastNode = sourceLast;
    } else {
        // Append at the end of the destination list.
        this.lastNode.next = sourceFirst;
        sourceFirst.prev = this.lastNode;
        this.lastNode = sourceLast;
    }

    // Update the sizes.
    this.size += list.size;
    list.size = 0;

    // Clear the source list's references so it becomes empty.
    list.firstNode = null;
    list.lastNode = null;
}

