    }

    // Traverse the source list and transfer each node to this list.
    // We keep a reference to the next node before removing the current one
    // to avoid losing the traversal chain.
    for (ListNode<E> node = list.head; node != null; /* no update here */) {
        // Store the next node before the removal operation.
        final ListNode<E> next = node.next;
        // Remove from source list and add to destination list.
        try {
            list.removeListNode(node);
            this.addListNode(node);
        } catch (RuntimeException ex) {
