private void addReverse(final File[] files) {
    // Return immediately if the array is null or empty
    if (files == null || files.length == 0) {
        return;
    }
    // Iterate over the array in reverse order, adding each non‑null file
    for (int i = files.length - 1; i >= 0; i--) {
        File file = files[i];
        if (file == null) {
            continue; // Skip null entries
        }
        try {
            // Assume an existing add(File) method that handles the actual addition
            add(file);
        } catch (Exception e) {
            // If an unexpected exception occurs, wrap it to preserve stack trace
            throw new RuntimeException("Failed to add file in reverse order: " + file, e);
        }
    }
}

