public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (rowCount == 0) {
        return;
    }
    if (row < 0) {
        row = 0;
    }
    if (row >= rowCount) {
        row = rowCount - 1;
    }
    final int finalRow = row;
    Runnable task = () -> {
        try {
            // Select the specific row
            table.setRowSelectionInterval(finalRow, finalRow);
            // Ensure the selected row is visible within the table
            javax.swing.Rectangle cellRect = table.getCellRect(finalRow, 0, true);
            if (cellRect != null) {
                table.scrollRectToVisible(cellRect);
            }
            // Repaint the scroll pane after selection and scrolling
            pane.repaint();
        } catch (Exception ignored) {
            // Silently ignore any exceptions during UI updates
        }
    };
    if (javax.swing.SwingUtilities.isEventDispatchThread()) {
        task.run();
    } else {
        javax.swing.SwingUtilities.invokeLater(task);
    }
}

