        throw new IllegalArgumentException("pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IndexOutOfBoundsException(
                "Row index out of bounds: " + row + ", table row count: " + table.getRowCount());
    }

    // Perform all UI updates on the Event Dispatch Thread
    SwingUtilities.invokeLater(() -> {
        try {
            // Select the specified row
            table.setRowSelectionInterval(row, row);

            // Ensure the selected row is visible within the viewport
            Rectangle cellRect = table.getCellRect(row, 0, true);
            if (cellRect != null) {
                table.scrollRectToVisible(cellRect);
            }

            // Deferred repaint to allow the table to paint the newly selected row
            SwingUtilities.invokeLater(() -> table.repaint());
        } catch (Exception e) {
            // Log or handle unexpected exceptions without propagating them
            e.printStackTrace();
        }
    });
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return; // nothing to do if components are missing
    }

    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return; // ignore out-of-bounds requests
    }

    SwingUtilities.invokeLater(() -> {
        // Select the desired row (and all columns for visibility)
        table.setRowSelectionInterval(row, row);
        if (table.getColumnCount() > 0) {
            table.setColumnSelectionInterval(0, table.getColumnCount() - 1);
        }

        // Ensure the row is visible within the scroll pane
        Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }

        // Schedule a repaint after a short delay to guarantee the row is painted
        javax.swing.Timer repaintTimer = new javax.swing.Timer(10, e -> {
            table.repaint();
            pane.repaint();
            ((javax.swing.Timer) e.getSource()).stop(); // stop the timer after one run
        });
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    });
}

public ByteVector putInt(final int intValue){
    // Ensure there is enough space for the new 4 bytes
    final int newCount = count + 4;
    if (newCount > buf.length) {
        int newCapacity = Math.max(buf.length * 2, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    // Store the int in big‑endian byte order
    buf[count++] = (byte)(intValue >> 24);
    buf[count++] = (byte)(intValue >> 16);
    buf[count++] = (byte)(intValue >> 8);
    buf[count++] = (byte)intValue;
    return this;
}

public ByteVector putInt(final int intValue) {
    // Ensure sufficient capacity for the 4 bytes of the integer
    if (pos + 4 > vector.length) {
        int newCap = Math.max(vector.length << 1, pos + 4);
        byte[] newVector = java.util.Arrays.copyOf(vector, newCap);
        vector = newVector;
    }
    // Write the integer in big-endian order
    vector[pos++] = (byte) (intValue >> 24);
    vector[pos++] = (byte) (intValue >> 16);
    vector[pos++] = (byte) (intValue >> 8);
    vector[pos++] = (byte) intValue;
    return this;
}

