    }
    // A subgraph with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
