    }
    // Check every unordered pair of distinct vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            // For undirected graphs this suffices; for directed graphs
            // this checks the existence of an edge from v1 to v2
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

