    if (keys == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }
    // Create a sorted copy of keys that are comparable and of type Integer
    List<Integer> sortedIntegers = new ArrayList<>();
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("All keys must be of type Integer");
        }
        sortedIntegers.add((Integer) key);
    }
    Collections.sort(sortedIntegers);
    // For each original key, find maximum lower bound (largest element <= key)
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        int target = (Integer) key;
        int idx = Collections.binarySearch(sortedIntegers, target);
        if (idx >= 0) {
            // Exact match found; lower bound is the key itself
            result.add(sortedIntegers.get(idx));
        } else {
            // No exact match; binarySearch returns -(insertionPoint) - 1
            int insertionPoint = -idx - 1;
            if (insertionPoint == 0) {
                // No element <= target
                result.add(null);
            } else {
                result.add(sortedIntegers.get(insertionPoint - 1));
            }
        }
    }
    return result;
}

