    char c = descriptor.charAt(pos);
    // Handle array types first
    while (c == '[') {
        pos++;
        if (pos >= descriptor.length()) {
            throw new IllegalArgumentException("Incomplete array type in descriptor");
        }
        c = descriptor.charAt(pos);
    }
    // If it's an object type, consume until the ';'
    if (c == 'L') {
        pos++; // skip 'L'
        while (pos < descriptor.length() && descriptor.charAt(pos) != ';') {
            pos++;
        }
        if (pos >= descriptor.length() || descriptor.charAt(pos) != ';') {
            throw new IllegalArgumentException("Missing ';' for object type in descriptor");
        }
        pos++; // skip ';'
    } else {
        // Primitive type – single character
        if ("BCDFIJSZV".indexOf(c) == -1) {
            throw new IllegalArgumentException("Unknown type code '" + c + "' in descriptor");
        }
        pos++; // skip primitive
    }
    popConsumer.accept(null);
    return pos;
