private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor must not be null or empty");
    }
    int length = descriptor.length();
    int index = 0;

    // Helper to consume a single type descriptor and return the new index.
    java.util.function.IntUnaryOperator consumeType = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int idx) {
            // Consume array brackets if any
            while (idx < length && descriptor.charAt(idx) == '[') {
                idx++;
            }
            if (idx >= length) {
                throw new IllegalArgumentException("Incomplete type descriptor");
            }
            char c = descriptor.charAt(idx);
            if (c == 'L') {
                idx++; // skip 'L'
                // Consume class name until ';'
                while (idx < length && descriptor.charAt(idx) != ';') {
                    idx++;
                }
                if (idx >= length) {
                    throw new IllegalArgumentException("Missing ';' in object type");
                }
                idx++; // skip ';'
            } else {
                // Primitive type (single char)
                idx++;
            }
            return idx;
        }
    };

    try {
        // If descriptor starts with '(' treat as method descriptor
        if (descriptor.charAt(0) == '(') {
            index = 1; // skip '('
            while (index < length && descriptor.charAt(index) != ')') {
                // Pop one type for each argument descriptor
                if (outputStack.isEmpty()) {
                    throw new IllegalStateException("Output stack underflow while popping method arguments");
                }
                outputStack.pop();
                index = consumeType.applyAsInt(index);
            }
            if (index >= length || descriptor.charAt(index) != ')') {
                throw new IllegalArgumentException("Malformed method descriptor: missing ')'");
            }
            // Return type is after ')', ignore it for popping
            // No need to validate further unless strict validation required
        } else {
            // Single type descriptor
            if (outputStack.isEmpty()) {
                throw new IllegalStateException("Output stack underflow while popping a type");
            }
            outputStack.pop();
            index = consumeType.applyAsInt(index);
            if (index != length) {
                throw new IllegalArgumentException("Extra characters after type descriptor");
            }
        }
    } catch (ArrayIndexOutOfBoundsException | IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

