    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int bound = 0;
        try {
            if (key != null && key instanceof Number) {
                bound = ((Number) key).intValue() + 1;
            }
        } catch (Exception ex) {
            // In case of unexpected conversion issues, keep bound as 0
        }
        result.add(bound);
    }
    return result;
}

private java.util.List<Integer> computeUpperBounds(java.util.List<K> keys) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(-1);
            continue;
        }
        int count = 0;
        boolean valid = true;
        for (K element : keys) {
            if (element == null) {
                continue;
            }
            try {
                @SuppressWarnings("unchecked")
                Comparable<? super K> cmp = (Comparable<? super K>) element;
                if (cmp.compareTo(key) <= 0) {
                    count++;
                }
            } catch (ClassCastException e) {
                valid = false;
                break;
            }
        }
        result.add(valid ? count : -1);
    }
    return result;
}

private List<Integer> computeUpperBounds(List<K> keys){
    // Return an empty list if input is null
    if (keys == null) {
        return new ArrayList<>();
    }
    List<Integer> result = new ArrayList<>(keys.size());
    // First collect all non-null Integer keys
    List<Integer> allInts = new ArrayList<>();
    for (K k : keys) {
        try {
            if (k != null) {
                allInts.add((Integer) k);
            }
        } catch (ClassCastException e) {
            // ignore non-Integer key
        }
    }
    // Sort the collected integers for binary search
    java.util.Collections.sort(allInts);
    for (K k : keys) {
        try {
            if (k == null) {
                result.add(null);
                continue;
            }
            Integer val = (Integer) k;
            int idx = java.util.Collections.binarySearch(allInts, val);
            int floorIndex;
            if (idx >= 0) {
                floorIndex = idx;
            } else {
                floorIndex = -idx - 2;
            }
            if (floorIndex >= 0) {
                result.add(allInts.get(floorIndex));
            } else {
                // No lower bound found
                result.add(null);
            }
        } catch (ClassCastException e) {
            // For non-Integer keys, we cannot compute a bound
            result.add(null);
        } catch (Exception e) {
            // Catch any unforeseen exceptions to keep method robust
            result.add(null);
        }
    }
    return result;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null || !(key instanceof Number)) {
            bounds.add(-1);
            continue;
        }
        int val = ((Number) key).intValue();
        int maxDiff = 0;
        for (K other : keys) {
            if (other == null || !(other instanceof Number)) {
                continue;
            }
            int otherVal = ((Number) other).intValue();
            int diff = Math.abs(val - otherVal);
            if (diff > maxDiff) {
                maxDiff = diff;
            }
        }
        bounds.add(maxDiff);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        try {
            int val = key.hashCode();
            bounds.add(val >= 0 ? val : 0);
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

