public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        return null;
    }

    // Trim any surrounding whitespace
    path = path.trim();
    relativePath = relativePath.trim();

    // If relativePath is empty or just ".", return the original path (or adjustment for trailing slash)
    if (relativePath.isEmpty() || ".".equals(relativePath)) {
        return path;
    }

    // Determine the base directory from the given full path.
    // If path ends with '/', treat it as a directory; otherwise, consider the part before the last '/'.
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        if (lastSlash < 0) {
            baseDir = "";
        } else {
            baseDir = path.substring(0, lastSlash + 1); // keep the slash for easy concatenation
        }
    }

    // Split the relative path into components
    String[] relParts = relativePath.split("/+");
    // Use a dynamic array (stack) to resolve '..' and '.' components
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    for (String part : relParts) {
        if (part.isEmpty() || ".".equals(part)) {
            // Skip these parts
            continue;
        } else if ("..".equals(part)) {
            if (!stack.isEmpty()) {
                stack.pop();
            } else {
                // If stack is empty and we encounter '..', we cannot go up further.
                // In a typical file system, this would remain at the root.
                // We simply ignore further '..' components to avoid invalid paths.
                // Alternatively, one could keep an explicit ".." component,
                // but for simplicity we ignore it.
            }
        } else {
            stack.push(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();

    // If baseDir got trimmed to empty string (relative file path) and we have stack components, we
    // start with an empty base; otherwise, use baseDir as the starting point.
    if (!baseDir.isEmpty()) {
        result.append(baseDir);
    }

    // Because we used a stack (LIFO), we need to reverse the order
    java.util.Iterator<String> it = stack.descendingIterator();
    while (it.hasNext()) {
        if (result.length() != 0 && result.charAt(result.length() - 1) != '/') {
            result.append('/');
        }
        result.append(it.next());
    }

    // If the result is still empty, it means the relative path resolved to the current directory.
    if (result.length() == 0) {
        result.append(".");
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Neither path nor relativePath can be null");
    }

    // Determine if the base path is absolute (starts with '/')
    boolean isAbsolute = path.startsWith("/");
    // Remove any trailing '/' from the base path to avoid empty components
    while (path.endsWith("/") && path.length() > 1) {
        path = path.substring(0, path.length() - 1);
    }

    // Split base path components
    String[] baseParts = path.split("/", -1); // -1 to keep possible leading empty token
    // Use a dynamic list to allow pop/push operations
    java.util.ArrayList<String> components = new java.util.ArrayList<>();
    // If the path was absolute, preserve the leading empty token
    if (isAbsolute) {
        components.add(""); // represents the root "/"
    }
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            components.add(part);
        }
    }

    // Normalize the relative path: treat leading '/' as relative (ignore it)
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Process each segment of the relative path
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory segments
            continue;
        } else if (part.equals("..")) {
            // Move up one directory unless at root
            if (components.size() > 1 || (!isAbsolute && !components.isEmpty())) {
                components.remove(components.size() - 1);
            }
        } else {
            // Normal directory/file segment
            components.add(part);
        }
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < components.size(); i++) {
        String comp = components.get(i);
        if (i > 0) {
            result.append('/');
        }
        result.append(comp);
    }

    // Handle the case where the result is an empty string (root directory)
    if (result.length() == 0) {
        return isAbsolute ? "/" : "";
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Path and relativePath must not be null");
        }

        // Trim any leading slash from the relativePath to keep it truly relative
        while (relativePath.startsWith("/")) {
            relativePath = relativePath.substring(1);
        }

        // Determine the base directory from the path
        int lastSep = path.lastIndexOf('/');
        String baseDir = (lastSep == -1) ? "" : path.substring(0, lastSep);

        // Combine base directory with the relative path
        String combined = baseDir.isEmpty() ? relativePath : baseDir + "/" + relativePath;

        // Normalize the combined path
        String[] parts = combined.split("/");
        Deque<String> stack = new ArrayDeque<>();

        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pollLast();
                }
            } else {
                stack.addLast(part);
            }
        }

        // Reconstruct the normalized path
        if (stack.isEmpty()) {
            return "/";
        }

        StringBuilder sb = new StringBuilder();
        for (String p : stack) {
            sb.append("/").append(p);
        }

        return sb.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }

    boolean startsWithSlash = path.startsWith("/");
    List<String> stack = new ArrayList<>();

    // Process the base path
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Process the relative path
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (startsWithSlash) {
        result.append("/");
    }

    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    return result.toString();
}

