        String[] produced = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            produced[i] = (String) array[i];
        }
        return produced;
    }
    String[] result = new String[array.length - nullCount];
    int pos = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[pos++] = (String) obj;
        }
    }
    return result;
}

