public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the position of the last '.' in the filename
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1; // No extension separator
    }

    // Determine the index of the last file separator ('/' or '\\')
    int slashIndex = filename.lastIndexOf('/');
    int backslashIndex = filename.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(slashIndex, backslashIndex);

    // If the dot occurs after the last separator, it's an extension
    return (dotIndex > lastSeparatorIndex) ? dotIndex : -1;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSeparatorIndex = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    // Return dot position only if it occurs after the last path separator
    return (dotIndex > lastSeparatorIndex) ? dotIndex : -1;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSep = indexOfLastSeparator(filename);
    // If a separator appears after the last dot, the dot is part of a directory name
    if (lastSep > lastDot) {
        return -1;
    }
    return lastDot;
}

private static int indexOfLastSeparator(String file) {
    if (file == null) {
        return -1;
    }
    int lastUnixSep = file.lastIndexOf('/');
    int lastWindowsSep = file.lastIndexOf('\\');
    return Math.max(lastUnixSep, lastWindowsSep);
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the index of the last dot
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }

    // Find the index of the last path separator (handles both Unix '/' and Windows '\\')
    int lastSlashIndex = filename.lastIndexOf('/');
    int lastBackslashIndex = filename.lastIndexOf('\\');
    int separatorIndex = Math.max(lastSlashIndex, lastBackslashIndex);

    // If there is a directory separator after the last dot, the dot does not denote an extension
    if (separatorIndex > dotIndex) {
        return -1;
    }

    return dotIndex;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }

    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }

    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator > lastDot) {
        // A directory separator comes after the last dot, so the dot is
        // part of a path segment, not the filename.
        return -1;
    }

    return lastDot;
}

public boolean isExpired(long timestamp, long expiredThreshold){
    try {
        if (timestamp < 0 || expiredThreshold < 0) {
            throw new IllegalArgumentException("Timestamp and expiredThreshold must be non-negative");
        }
        long now = System.currentTimeMillis();
        return (now - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, consider the metric expired to avoid stale data
        return true;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp cannot be negative: " + timestamp);
    }
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("Expired threshold cannot be negative: " + expiredThreshold);
    }
    long current = System.currentTimeMillis();
    if (current < timestamp) {
        // Timestamp is in the future; consider it not expired
        return false;
    }
    return current - timestamp > expiredThreshold;
}

