    try {
        if (expiredThreshold < 0) {
            throw new IllegalArgumentException("expiredThreshold must be non-negative");
        }
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future, it cannot be expired yet.
        if (timestamp > currentTime) {
            return false;
        }
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, treat the metric as not expired.
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            // Non‑positive threshold considered expired immediately
            return true;
        }
        long currentTime = System.currentTimeMillis();
        if (timestamp > currentTime) {
            // Future timestamp; treat as not expired
            return false;
        }
        return currentTime - timestamp > expiredThreshold;
    } catch (Exception e) {
        // In case of any runtime issue, conservatively consider expired
        return true;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // Validate input values
        if (timestamp < 0) {
            throw new IllegalArgumentException("timestamp must be non‑negative");
        }
        if (expiredThreshold < 0) {
            throw new IllegalArgumentException("expiredThreshold must be non‑negative");
        }

        long currentTime = System.currentTimeMillis();

        // If the timestamp is in the future, it cannot be expired yet
        if (timestamp > currentTime) {
            return false;
        }

        // Calculate elapsed time; an overflow would wrap to a negative value,
        // which correctly causes the item to be considered not expired.
        return (currentTime - timestamp) >= expiredThreshold;
    } catch (Exception e) {
        // If any unexpected issue occurs (e.g., SecurityException from
        // System.currentTimeMillis()), conservatively consider it not
        // expired to avoid accidental cache removal.
        return false;
    }
}

Edge edgeToNext(){
    // Ensure the iterator that provides nodes has been initialized
    if (nodeIterator == null) {
        throw new IllegalStateException("Node iterator has not been initialized.");
    }

    // Attempt to fetch the next node; throw if none available
    Node nextNode;
    try {
        nextNode = nodeIterator.next();
    } catch (NoSuchElementException e) {
        throw new NoSuchElementException("No next node available for edge construction.");
    }

    // On the very first call there is no previous node, so no edge can be formed yet.
    if (previousNode == null) {
        previousNode = nextNode;
        return null;
    }

    // Resolve real counterparts if either node is virtual
    Node start = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
    Node end   = nextNode.isVirtual()    ? nextNode.getRealNode() : nextNode;

    if (start == null || end == null) {
        throw new IllegalArgumentException("Encountered null node during edge creation.");
    }

    // Create the edge and update state for the next call
    Edge edge = new Edge(start, end);
    previousNode = nextNode;
    return edge;
}

public Edge edgeToNext() {
    try {
        // Obtain the node that was previously returned and the node that will be returned next.
        Node previous = this.previousNode; // previously returned node
        Node next      = this.nextNode;     // node to be returned next

        // If either node is missing, we cannot construct an edge.
        if (previous == null || next == null) {
            return null;
        }

        // If either node is a virtual node, replace it with its real counterpart.
        if (previous.isVirtual()) {
            previous = previous.getRealNode();
        }
        if (next.isVirtual()) {
            next = next.getRealNode();
        }

        // Construct and return the edge connecting the two real nodes.
        return new Edge(previous, next);
    } catch (Exception e) {
        // Any unexpected error results in returning null, preserving stability.
        return null;
    }
}

