    }
    java.util.List<java.net.Socket> sockets;
    try {
        sockets = connectedSockets; // assume this field exists in the class
    } catch (Exception e) {
        // If the list of sockets cannot be obtained, nothing can be done
        return;
    }
    for (java.net.Socket socket : sockets) {
        try {
            java.io.PrintWriter out = new java.io.PrintWriter(socket.getOutputStream(), true);
            out.println(message);
        } catch (java.io.IOException ex) {
            // Log or handle the broken connection as appropriate
        }
    }
}

protected void append(LoggingEvent event){
    // Format the event into a string
    String message;
    if (layout != null) {
        message = layout.format(event);
    } else {
        message = event.getRenderedMessage();
    }
    if (message == null) {
        message = "";
    }

    // Write to each connected client
    synchronized (connectedClients) {
        java.util.Iterator<?> it = connectedClients.iterator();
        while (it.hasNext()) {
            Object obj = it.next();
            try {
                if (obj instanceof Client) {
                    ((Client) obj).send(message);
                } else if (obj instanceof java.io.OutputStream) {
                    java.io.OutputStream out = (java.io.OutputStream) obj;
                    out.write(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));
                    out.flush();
                } else if (obj instanceof java.io.Writer) {
                    java.io.Writer w = (java.io.Writer) obj;
                    w.write(message);
                    w.flush();
                } else {
                    // Unsupported client type; skip
                }
            } catch (Exception e) {
                // Remove the client on failure and attempt to close it
                it.remove();
                if (obj instanceof java.io.Closeable) {
                    try {
                        ((java.io.Closeable) obj).close();
                    } catch (Exception ignored) {}
                }
            }
        }
    }
}

protected void append(LoggingEvent event){
    if (event == null) {
        return;
    }
    // Obtain the raw message from the logging event
    Object msgObj = event.getMessage();
    if (msgObj == null) {
        return;
    }
    String message = msgObj.toString();
    // Convert the message to bytes once for efficiency (UTF‑8)
    byte[] messageBytes = message.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    /*
     * Iterate over all connected clients. Each client is expected to provide an
     * OutputStream (or something compatible with write/flush). If any client
     * throws an exception while receiving the log, we simply log the error and
     * continue with the next client so that a single failure does not stop the
     * logger.
     */
    for (java.io.OutputStream out : outputStreams) {
        try {
            out.write(messageBytes);
            out.flush();
        } catch (Exception ex) {
            // Optionally report the error, e.g. via an error handler
            if (errorHandler != null) {
                errorHandler.error("Failed to send log to client", ex, LoggingEvent.ERROR);
            }
            // otherwise swallow and continue
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }

    String message = event.getMessage();
    if (message == null) {
        message = "";
    }

    // Iterate over all connected clients and send the formatted log message.
    // Thread safety is maintained by synchronizing on the client list.
    synchronized (clients) {
        Iterator<?> iterator = clients.iterator();
        while (iterator.hasNext()) {
            Object clientObj = iterator.next();
            try {
                // Assumes each client has a write(String) method that may throw IOException.
                // If the actual client type is different, adjust accordingly.
                clientObj.getClass()
                         .getMethod("write", String.class)
                         .invoke(clientObj, message);
            } catch (Exception e) {
                // If writing fails (e.g., client disconnected), log the error,
                // remove the client from the list, and close its resources if possible.
                logger.error("Failed to send log message to a client", e);
                try {
                    // Attempt to close possible resources
                    clientObj.getClass()
                             .getMethod("close")
                             .invoke(clientObj);
                } catch (Exception ignore) {
                    // Ignore any further errors during cleanup
                }
                iterator.remove();
            }
        }
    }
}

