    int firstByte = input.read();
    if (firstByte == -1) {
        return 0;
    }

    // The tag is a varint.  Decode it here.
    int tag = firstByte & 0x7F;
    if ((firstByte & 0x80) == 0) {
        // Single‑byte tag; return it directly.
        return tag;
    }

    int shift = 7;
    for (int i = 0; i < 4; i++) {        // we may need up to 5 bytes total
        int next = input.read();
        if (next == -1) {
            throw new IOException("Unexpected EOF while reading tag");
        }
        tag |= (next & 0x7F) << shift;
        if ((next & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }

    // If we get here, we have read 5 bytes and the continuation bit is still set,
    // which means the tag is too long.  This is considered a malformed varint.
    throw new IOException("Tag is too long (more than 5 bytes)");
}

