private String buildContentRange() {
    try {
        java.lang.reflect.Field startField = this.getClass().getDeclaredField("start");
        java.lang.reflect.Field endField = this.getClass().getDeclaredField("end");
        java.lang.reflect.Field totalField = this.getClass().getDeclaredField("totalSize");
        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);
        Object startObj = startField.get(this);
        Object endObj = endField.get(this);
        Object totalObj = totalField.get(this);
        String start = startObj != null ? startObj.toString() : "0";
        String end = endObj != null ? endObj.toString() : "0";
        String total = totalObj != null ? totalObj.toString() : "*";
        return "bytes " + start + "-" + end + "/" + total;
    } catch (Exception e) {
        return null;
    }
}

private String buildContentRange(){
    try {
        // Assume instance fields: contentLength (total bytes), startOffset, endOffset
        if (contentLength <= 0) {
            return null;
        }
        if (startOffset < 0 || endOffset < startOffset || endOffset >= contentLength) {
            return null;
        }
        return String.format("bytes %d-%d/%d", startOffset, endOffset, contentLength);
    } catch (Exception e) {
        // If any unexpected error occurs, return null to avoid propagating
        return null;
    }
}

private String buildContentRange() {
    try {
        // Assuming the class has fields: long start, long end, long total.
        // If fields are named differently, replace them accordingly.
        long start = this.start;
        long end = this.end;
        long total = this.total;

        // Validate values
        if (total <= 0) {
            return ""; // Total length must be positive to form a valid range
        }
        if (start < 0 || end < start) {
            // Invalid range; return a minimal Content-Range indicating no data
            return String.format("bytes */%d", total);
        }
        return String.format("bytes %d-%d/%d", start, end, total);
    } catch (Exception e) {
        // In case of any unforeseen errors, return an empty string
        return "";
    }
}

