        return result;
    }
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip empty or whitespace-only lines
            if (line.trim().isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static factory method `fromString`
                snapshot = ThreadSnapshot.fromString(line);
            } catch (Exception e) {
                // If parsing fails, skip this line
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            long ts = snapshot.getTimestamp(); // Assume method returns a long timestamp
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStart(); // Assume getters exist
                long end = range.getEnd();
