public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Validate input arguments
    if (file == null) {
        throw new IllegalArgumentException("The file argument cannot be null.");
    }
    if (!file.exists()) {
        throw new IOException("The specified file does not exist: " + file.getPath());
    }
    if (!file.isFile()) {
        throw new IOException("The specified path does not refer to a regular file: " + file.getPath());
    }
    if (!file.canRead()) {
        throw new IOException("The specified file cannot be read: " + file.getPath());
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("The timeRanges argument cannot be null.");
    }

    List<ThreadSnapshot> snapshotsInRange = new ArrayList<>();
    // If there are no ranges, there's nothing to filter, return empty list
    if (timeRanges.isEmpty()) {
        return snapshotsInRange;
    }

    // Determine the global start and end that covers all ranges to allow early exit
    long globalStart = Long.MAX_VALUE;
    long globalEnd = Long.MIN_VALUE;
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (range == null) {
            continue; // skip null range
        }
        long start = range.getStart();
        long end = range.getEnd();
        if (start < globalStart) {
            globalStart = start;
        }
        if (end > globalEnd) {
            globalEnd = end;
        }
    }
    // If global range is invalid, return empty
    if (globalStart > globalEnd) {
        return snapshotsInRange;
    }

    // Read objects from the file
    try (FileInputStream fis = new FileInputStream(file);
         BufferedInputStream bis = new BufferedInputStream(fis);
         ObjectInputStream ois = new ObjectInputStream(bis)) {

        while (true) {
            Object obj;
            try {
                obj = ois.readObject();
            } catch (EOFException e) {
                // End-of-file reached
                break;
            } catch (ClassNotFoundException e) {
                // Skip unknown objects
                continue;
            }

            if (!(obj instanceof ThreadSnapshot)) {
                // Skip unexpected objects
                continue;
            }
            ThreadSnapshot snapshot = (ThreadSnapshot) obj;
            long ts = snapshot.getTimestamp(); // assume this method exists
            if (ts < globalStart || ts > globalEnd) {
                // Outside any requested range; skip
                continue;
            }
            // Check each range for containment
            boolean contains = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                if (ts >= range.getStart() && ts <= range.getEnd()) {
                    contains = true;
                    break;
                }
            }
            if (contains) {
                snapshotsInRange.add(snapshot);
            }
        }
    } catch (IOException e) {
        // Propagate I/O issues to caller
        throw e;
    }

    return snapshotsInRange;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Provided file does not exist or is not a regular file");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        // No filtering requested – read everything
        return parseAllSnapshots(file);
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            // Expected format: "<timestamp> <snapshot data>"
            int firstSpace = line.indexOf(' ');
            if (firstSpace <= 0) {
                // Skip lines that do not conform to the expected format
                continue;
            }

            long timestamp;
            try {
                timestamp = Long.parseLong(line.substring(0, firstSpace));
            } catch (NumberFormatException e) {
                // Skip lines where the timestamp is not a valid long
                continue;
            }

            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                try {
                    if (range.contains(timestamp)) {
                        inRange = true;
                        break;
                    }
                } catch (Exception e) {
                    // If a range throws an exception (e.g., null bounds), skip that range
                    continue;
                }
            }
            if (!inRange) {
                continue;
            }

            String snapshotData = line.substring(firstSpace + 1);
            try {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, snapshotData);
                result.add(snapshot);
            } catch (Exception e) {
                // If constructing a snapshot fails, skip this line
                continue;
            }
        }
    } catch (IOException e) {
        // Propagate IOExceptions as requested
        throw e;
    } catch (Exception e) {
        // Wrap any unexpected exception in an IOException
        throw new IOException("Unexpected error while parsing thread snapshots", e);
    }

    return result;
}

